import { test, expect } from "../../../../core/fixtures/index";
import type { Page, Locator } from "@playwright/test";
import fs from "node:fs";

const SHOT_DIR = "tools/tour2playwright/generated/screenshots/finance-accounts-receivable-ageing-by-customer-didula-power-all-durations-full-flow";

// Keep a screenshot of the finished screen (a step's own screenshot is taken BEFORE its action).
async function resultShot(page: Page, file: string) {
  fs.mkdirSync(SHOT_DIR, { recursive: true });
  await page.screenshot({ path: SHOT_DIR + "/" + file });
}

// Screenshot the current page with the target element outlined.
async function shot(page: Page, loc: Locator, file: string) {
  try {
    await loc.scrollIntoViewIfNeeded({ timeout: 5000 });
    await loc.evaluate((el) => el.setAttribute("data-t2p", "1"));
    await page.addStyleTag({
      content: '[data-t2p="1"]{outline:3px solid #e01e5a !important;outline-offset:2px !important;}',
    });
  } catch {}
  fs.mkdirSync(SHOT_DIR, { recursive: true });
  await page.screenshot({ path: `${SHOT_DIR}/${file}` });
  try { await loc.evaluate((el) => el.removeAttribute("data-t2p")); } catch {}
}

test.describe("Finance: Accounts Receivable Ageing by Customer ( Didula Power - All Durations ) - Full Flow @module:accounting @step:business @e2e", () => {
  // At the default 1280px some top-menu entries collapse into the "+" overflow.
  test.use({ viewport: { width: 1600, height: 900 } });

  test("Finance: Accounts Receivable Ageing by Customer ( Didula Power - All Durations ) - Full Flow", async ({ page }) => {
    await page.goto("/web");

    // The saved browser session can expire — fall back to the login form if we got bounced to it.
    const emailBox = page.getByRole("textbox", { name: "Email" });
    if (await emailBox.isVisible({ timeout: 8_000 }).catch(() => false)) {
      await emailBox.fill(process.env.ADMIN_EMAIL ?? "admin");
      await page.getByRole("textbox", { name: "Password" }).fill(process.env.ADMIN_PASSWORD ?? "admin");
      await page.getByRole("button", { name: "Log in" }).click();
      await page.waitForSelector(".o_main_navbar, .o_home_menu", { state: "visible", timeout: 45_000 });
    }
    // Odoo keeps persistent long-polling/websocket connections open for
    // real-time notifications, so "networkidle" never naturally resolves —
    // bound it explicitly or it silently eats the whole test timeout as its
    // fallback ceiling before its own .catch() ever fires.
    await page.waitForLoadState("networkidle", { timeout: 10_000 }).catch(() => {});

    await test.step("01. Open Accounting app", async () => {
      const loc = (page.locator("[data-menu-xmlid=\"account_accountant.menu_accounting\"]")).first();
      await loc.waitFor({ state: "visible", timeout: 45000 });
      await shot(page, loc, "step-01.png");
      await loc.click();
    });

    await test.step("02. Reporting", async () => {
      const loc = (page.locator("[data-menu-xmlid=\"account.menu_finance_reports\"]")).first();
      await loc.waitFor({ state: "visible", timeout: 45000 });
      await shot(page, loc, "step-02.png");
      await loc.click();
    });

    await test.step("03. Aged Receivable", async () => {
      const loc = (page.locator("[data-menu-xmlid=\"account_reports.menu_action_account_report_aged_receivable\"]")).first();
      await loc.waitFor({ state: "visible", timeout: 45000 });
      await shot(page, loc, "step-03.png");
      await loc.click();
      await expect(page, "Aged Receivable report opened").toHaveTitle(/Aged Receivable/);
      await page.locator("table tbody tr").first().waitFor({ state: "visible", timeout: 30000 });
      await resultShot(page, "step-03-result.png");
    });

    await test.step("04. As of date - report cut-off", async () => {
      const loc = (page.locator("div.filter_date > div.o-dropdown.dropdown > button.dropdown-toggle.btn")).first();
      await loc.waitFor({ state: "visible", timeout: 45000 });
      await shot(page, loc, "step-04.png");
      await expect(loc).toBeVisible();
    });

    await test.step("05. Partners", async () => {
      const loc = (page.locator("div.filter_partner > div.o-dropdown.dropdown > button.dropdown-toggle.btn")).first();
      await loc.waitFor({ state: "visible", timeout: 45000 });
      await shot(page, loc, "step-05.png");
      await loc.click();
    });

    await test.step("06. Search for the customer", async () => {
      const loc = (page.locator("div.dropdown-item:nth-of-type(1) > div.o_input.d-flex > div.o-autocomplete.o_record_autocomplete_with_caret > input.o-autocomplete--input.o_input")).first();
      await loc.waitFor({ state: "visible", timeout: 45000 });
      await shot(page, loc, "step-06.png");
      await loc.fill("Didula power");
    });

    await test.step("07. DIDULA POWER ELECTRICLES (PVT) LIMITED,", async () => {
      // Recorded as #autocomplete_0_0 (a position) — pick the customer by its name.
      const loc = (page.locator(".o-autocomplete--dropdown-item").filter({ hasText: "DIDULA POWER ELECTRICLES" })).first();
      await loc.waitFor({ state: "visible", timeout: 45000 });
      await shot(page, loc, "step-07.png");
      await loc.click();
      // The customer is also visible in the UNFILTERED list, so "is visible" proves nothing — wait until the report
      // has really reloaded down to exactly this one customer.
      await expect(page.locator("tr.line_level_2"), "report filtered to a single customer").toHaveCount(1, { timeout: 30000 });
      await expect(page.locator("tr.line_level_2 .name").filter({ hasText: "DIDULA POWER" })).toHaveCount(1);
      await resultShot(page, "step-07-result.png");
    });

    await test.step("08. Unfold the customer line", async () => {
      // Pick the customer line by its name.
      const loc = (page.locator("tr.line_level_2 .name").filter({ hasText: "DIDULA POWER" })).first();
      await loc.waitFor({ state: "visible", timeout: 45000 });
      await shot(page, loc, "step-08.png");
      const rowsBefore = await page.locator("table tbody tr").count();
      await loc.click();
      await expect.poll(() => page.locator("table tbody tr").count(), { message: "unfolding should list the entries behind the balance" }).toBeGreaterThan(rowsBefore);
      await resultShot(page, "step-08-result.png");
    });

    await test.step("09. All ageing durations", async () => {
      // Recorded as the 8th column (th:nth-of-type(8)), which outlines just one bucket — outline the whole header row.
      const loc = (page.locator("thead tr")).last();
      await loc.waitFor({ state: "visible", timeout: 45000 });
      await shot(page, loc, "step-09.png");
      await expect(loc).toBeVisible();
      // The report always shows every ageing duration — check each column is really there.
      for (const col of ["At Date", "1-30", "31-60", "61-90", "91-120", "Older", "Total"]) {
        await expect(page.locator("thead"), "ageing column " + col).toContainText(col);
      }
    });

    await test.step("10. Export the ageing report", async () => {
      // Recorded by DOM position — pick the export button by its name.
      // Odoo renders the export buttons twice (a collapsed small-screen copy and the real one) — use the visible one.
      const loc = (page.locator("button:visible").filter({ hasText: /^PDF$/ })).first();
      await loc.waitFor({ state: "visible", timeout: 45000 });
      await shot(page, loc, "step-10.png");
      await expect(loc).toBeVisible();
      await expect(page.locator("button:visible").filter({ hasText: /^XLSX$/ }).first()).toBeVisible();
    });

  });
});
